{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Theophylline, the highest-transfer analogue, has essentially 100% absolute oral bioavailability in healthy subjects, demonstrating that this heterocyclic scaffold class can be completely absorbed without significant first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Voriconazole, a fluorinated azole with multiple aromatic and heteroaromatic rings, has a mean absolute oral bioavailability of 96% in healthy volunteers, supporting high F for a similarly complex fluorinated heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Aprepitant, a larger lipophilic molecule with multiple aromatic/heteroaromatic rings and known solubility challenges, still achieves 67% absolute oral bioavailability in humans, showing that molecular complexity does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Linezolid has 100% absolute oral bioavailability in healthy volunteers, providing direct human evidence that polar heterocyclic drugs in this transfer range can be completely orally absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tegafur, a fluorinated heterocyclic compound, is almost 100% bioavailable in humans, supporting high oral bioavailability for fluorinated heterocycles.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability well above the 20% threshold, including absolute human measurements ranging from ~59% to 100%. The favorable physicochemical prior and absence of any low-bioavailability evidence support a high F prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "Solubility and metabolic stability of the query are not directly measured; low Fsp3 and multiple aromatic rings could pose unquantified risks.",
    "No low-bioavailability analogue with comparable transfer score was provided to challenge the high prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

